-- STEP A — Akure Humboldt Kolleg 2027 release (GENERATED by scripts/build-release-sql.sh; do not edit)
-- Applies 20261117000100 (no-op on live) and 20261117000200 (additive; compatible
-- with the currently deployed app). One transaction: any failed check rolls back.
begin;

-- Snapshot the state that must not change.
create temporary table _release_pre on commit drop as
select s.demo_mode, s.registration_open, s.submissions_open, s.registration_deadline, s.abstract_deadline,
       (select count(*) from public.registrations) as registrations,
       (select count(*) from public.abstracts) as abstracts,
       (select count(*) from public.reviews) as reviews,
       (select count(*) from public.user_roles) as user_roles
from public.conference_settings s where s.id = 1;

do $pre$ begin
  if not (select demo_mode from _release_pre) then
    raise exception 'STEP A precondition failed: demo_mode must be true (pre-launch test mode)';
  end if;
  if to_regprocedure('public.find_conference_account(text)') is null
     or to_regprocedure('public.conference_reviewer_directory()') is null then
    raise exception 'STEP A precondition failed: the two live organiser functions are missing; run the drift check';
  end if;
end $pre$;

-- ===== begin 20261117000100_reconcile_reviewer_directory_functions.sql =====
-- Reconcile two functions that exist in the live conference database but were
-- never committed to the repository:
--   public.find_conference_account(p_email text)   -> table(user_id uuid, user_email text)
--   public.conference_reviewer_directory()          -> table(user_id uuid, user_email text)
--
-- The bodies below are the EXACT live definitions retrieved with
-- pg_get_functiondef() on 2026-11-18 (docs/audit/2026-11-18_live_function_reference.sql),
-- including their organiser checks and input validation. The executable
-- privileges match the live ACL:
--   {postgres=X/postgres, authenticated=X/postgres, service_role=X/postgres}
-- (no PUBLIC, no anon).
--
-- SAFETY: each function is created ONLY IF IT DOES NOT ALREADY EXIST.
--   * On the live project this migration is a no-op: the live functions, owners
--     and grants are left exactly as they are.
--   * On a fresh project (staging rebuild, CI, disaster recovery) it recreates
--     them identically.

do $migration$
begin
  if to_regprocedure('public.conference_reviewer_directory()') is null then
    execute $fn$
CREATE OR REPLACE FUNCTION public.conference_reviewer_directory()
 RETURNS TABLE(user_id uuid, user_email text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
 if auth.uid() is null or not private.has_role('organiser') then
  raise exception 'Organiser access required';
 end if;
 return query select u.id,u.email::text
 from auth.users u join public.user_roles ur on ur.user_id=u.id
 where ur.role='reviewer' order by lower(u.email);
end
$function$;
    $fn$;
    revoke all on function public.conference_reviewer_directory() from public, anon;
    grant execute on function public.conference_reviewer_directory() to authenticated, service_role;
  end if;

  if to_regprocedure('public.find_conference_account(text)') is null then
    execute $fn$
CREATE OR REPLACE FUNCTION public.find_conference_account(p_email text)
 RETURNS TABLE(user_id uuid, user_email text)
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
begin
  if auth.uid() is null or not private.has_role('organiser') then
    raise exception 'Organiser access required';
  end if;
  if p_email is null or length(trim(p_email)) < 5 or length(p_email)>255 then
    raise exception 'Invalid email';
  end if;
  return query select u.id, u.email::text from auth.users u
  where lower(u.email) = lower(trim(p_email)) limit 1;
end;
$function$;
    $fn$;
    revoke all on function public.find_conference_account(text) from public, anon;
    grant execute on function public.find_conference_account(text) to authenticated, service_role;
  end if;
end
$migration$;

-- ===== end 20261117000100_reconcile_reviewer_directory_functions.sql =====

-- ===== begin 20261117000200_reviewer_admin_and_launch_controls.sql =====
-- Reviewer-role administration and consistent launch controls.
-- Additive and non-destructive: no rows are deleted or rewritten, no RLS policy
-- is loosened, and direct writes to user_roles remain revoked from clients.

------------------------------------------------------------------------------
-- 1. Audit columns
------------------------------------------------------------------------------
alter table public.user_roles
  add column if not exists granted_by uuid references auth.users(id) on delete set null;

alter table public.conference_settings
  add column if not exists updated_by uuid references auth.users(id) on delete set null;

-- Keep updated_at / updated_by trustworthy whatever the client sends.
create or replace function private.stamp_conference_settings()
returns trigger language plpgsql security definer set search_path = '' as $$
begin
  new.updated_at := now();
  new.updated_by := (select auth.uid());
  return new;
end$$;
revoke all on function private.stamp_conference_settings() from public, anon, authenticated;
drop trigger if exists stamp_conference_settings on public.conference_settings;
create trigger stamp_conference_settings before update on public.conference_settings
for each row execute function private.stamp_conference_settings();

-- demo_mode is deliberately NOT client-updatable (see the existing column
-- grant): moving from test records to official records is a reviewed database
-- operation, documented in docs/LAUNCH_TRANSITION.md.

------------------------------------------------------------------------------
-- 2. Reviewer-role administration (organiser only, audited)
--    Clients still cannot insert/update/delete user_roles directly. These two
--    SECURITY DEFINER functions are the only path, and each verifies the caller
--    holds the organiser role. They can grant/revoke the reviewer role only;
--    organiser roles stay under database-administrator control.
------------------------------------------------------------------------------
create or replace function public.grant_conference_reviewer(p_email text)
returns table(user_id uuid, user_email text)
language plpgsql volatile security definer set search_path = '' as $$
#variable_conflict use_column
declare
  v_user uuid;
  v_email text;
begin
  if not private.has_role('organiser') then
    raise exception 'organiser role required' using errcode = '42501';
  end if;
  select u.id, u.email::text into v_user, v_email
  from auth.users u where lower(u.email) = lower(btrim(p_email)) limit 1;
  if v_user is null then
    raise exception 'no conference account for that email' using errcode = 'P0002';
  end if;
  -- Same rule as the live roles_organiser_add_reviewer policy: no self-grant.
  if v_user = (select auth.uid()) then
    raise exception 'organisers cannot grant the reviewer role to themselves' using errcode = '42501';
  end if;
  insert into public.user_roles(user_id, role, granted_by)
  values (v_user, 'reviewer', (select auth.uid()))
  on conflict (user_id, role) do nothing;
  if not found then
    raise exception 'account is already a reviewer' using errcode = '23505';
  end if;
  return query select v_user, v_email;
end$$;
revoke all on function public.grant_conference_reviewer(text) from public, anon;
grant execute on function public.grant_conference_reviewer(text) to authenticated;

create or replace function public.revoke_conference_reviewer(p_user_id uuid)
returns boolean
language plpgsql volatile security definer set search_path = '' as $$
begin
  if not private.has_role('organiser') then
    raise exception 'organiser role required' using errcode = '42501';
  end if;
  delete from public.user_roles where user_id = p_user_id and role = 'reviewer';
  return found;
end$$;
revoke all on function public.revoke_conference_reviewer(uuid) from public, anon;
grant execute on function public.revoke_conference_reviewer(uuid) to authenticated;

------------------------------------------------------------------------------
-- 3. Launch gates: also enforce published deadlines in the database.
--    Each policy keeps every existing condition and adds the deadline check,
--    so these replacements are strictly tighter than the current policies.
------------------------------------------------------------------------------
drop policy if exists reg_owner_insert on public.registrations;
create policy reg_owner_insert on public.registrations for insert to authenticated
with check (
  user_id = (select auth.uid())
  and lower(email) = lower((select auth.jwt()->>'email'))
  and consent_data = true
  and exists (
    select 1 from public.conference_settings s
    where s.id = 1 and s.registration_open
      and public.registrations.is_demo = s.demo_mode
      and (s.registration_deadline is null or now() < s.registration_deadline)
  )
);

drop policy if exists abstract_owner_insert on public.abstracts;
create policy abstract_owner_insert on public.abstracts for insert to authenticated
with check (
  user_id = (select auth.uid()) and status = 'submitted' and is_published = false and decision_at is null
  and exists (
    select 1 from public.conference_settings s
    where s.id = 1 and s.submissions_open
      and public.abstracts.is_demo = s.demo_mode
      and (s.abstract_deadline is null or now() < s.abstract_deadline)
  )
  and exists (
    select 1 from public.registrations r
    where r.id = public.abstracts.registration_id
      and r.user_id = (select auth.uid())
      and r.is_demo = public.abstracts.is_demo
  )
);

-- Attachments can only be uploaded while submissions are open.
drop policy if exists abstract_files_owner_upload on storage.objects;
create policy abstract_files_owner_upload on storage.objects for insert to authenticated
with check (
  bucket_id = 'abstract-files'
  and (storage.foldername(name))[1] = (select auth.uid())::text
  and exists (select 1 from public.registrations r where r.user_id = (select auth.uid()))
  and exists (
    select 1 from public.conference_settings s
    where s.id = 1 and s.submissions_open
      and (s.abstract_deadline is null or now() < s.abstract_deadline)
  )
);

-- ===== end 20261117000200_reviewer_admin_and_launch_controls.sql =====

do $post$ declare p record; begin
  select * into p from _release_pre;
  if (select (demo_mode, registration_open, submissions_open, registration_deadline, abstract_deadline)
             is distinct from (p.demo_mode, p.registration_open, p.submissions_open, p.registration_deadline, p.abstract_deadline)
      from public.conference_settings where id = 1) then
    raise exception 'STEP A postcondition failed: launch settings changed';
  end if;
  if (select count(*) from public.registrations) <> p.registrations or (select count(*) from public.abstracts) <> p.abstracts
     or (select count(*) from public.reviews) <> p.reviews or (select count(*) from public.user_roles) <> p.user_roles then
    raise exception 'STEP A postcondition failed: row counts changed';
  end if;
  if to_regprocedure('public.grant_conference_reviewer(text)') is null or to_regprocedure('public.revoke_conference_reviewer(uuid)') is null then
    raise exception 'STEP A postcondition failed: reviewer administration functions not created';
  end if;
  if has_function_privilege('anon', 'public.grant_conference_reviewer(text)', 'EXECUTE')
     or has_function_privilege('anon', 'public.revoke_conference_reviewer(uuid)', 'EXECUTE') then
    raise exception 'STEP A postcondition failed: anon can execute reviewer administration';
  end if;
  raise notice 'STEP A verified: settings and row counts unchanged; reviewer administration functions present and closed to anon';
end $post$;
commit;
